return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'skr','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:51:08+00:00','po-revision-date'=>'2026-11-05T19:51:08+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'تہاݙی سائٹ تے پہلے توں انسٹال کیتے ہوئے پلگ اِنز تے تھیمز دے گمشدہ ترجمے پورے کریندا ہے۔','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'اوہ اپ لوڈ سکرین پرانی ہو گئی ہئی: اوں دے بعد اک ہور اپ لوڈ تیار کیتا گیا ہے۔ کجھ نہیں بھیجیا گیا۔ موجودہ والی ترجمیاں دی لسٹ وچوں ݙیکھو۔','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'مفت سروس پلان ہر سائٹ کوں پلگ اِنز تے تھیمز کیتے سلاٹس دی محدود گنتی ݙیندا ہے؛ Babilim فعال کرݨ دے بعد ورتے ہوئے سلاٹس ترتیباں وچ ݙکھائے ویندے ہن۔','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'ترجمے دی درخواست کرݨ نال ایہ پلگ اِن یا تھیم اس سائٹ کیتے مفت سروس پلان دے سلاٹس وچوں اک تے آ ویندا ہے (حد تھیمز کیتے %1$d تے پلگ اِنز کیتے %2$d ہے)، جے پہلے توں اک تے نہ ہووے۔ سلاٹ ورتیا ہویا رہندا ہے، تے ناکام ترجمہ اینکوں خالی نہیں کریندا۔','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'ترجمے دی درخواست کرݨ نال ایہ پلگ اِن یا تھیم اس سائٹ کیتے مفت سروس پلان دے سلاٹس وچوں اک تے آ ویندا ہے، جے پہلے توں اک تے نہ ہووے۔ سلاٹ ورتیا ہویا رہندا ہے، تے ناکام ترجمہ اینکوں خالی نہیں کریندا۔','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'جے ایہ پلگ اِن یا تھیم اڄݨ اس سائٹ کیتے مفت سروس پلان دے سلاٹس وچوں کنہیں تے نہیں، تاں ترجمے دی درخواست کرݨ نال ایہ اک تے آ ویندا ہے (حد تھیمز کیتے %1$d تے پلگ اِنز کیتے %2$d ہے)۔ سلاٹ ورتیا ہویا رہندا ہے، تے ناکام ترجمہ اینکوں خالی نہیں کریندا۔ جاری رکھو؟','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'جے ایہ پلگ اِن یا تھیم اڄݨ اس سائٹ کیتے مفت سروس پلان دے سلاٹس وچوں کنہیں تے نہیں، تاں ترجمے دی درخواست کرݨ نال ایہ اک تے آ ویندا ہے۔ سلاٹ ورتیا ہویا رہندا ہے، تے ناکام ترجمہ اینکوں خالی نہیں کریندا۔ جاری رکھو؟','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'ایں نیٹ ورک تے %1$d سائٹ ایں طرح سیٹ ہے جو پلگ ان مٹاونْ تے اپݨی Babilim شناخت مٹا ݙیوے۔ پھر ایں سائٹ نال جڑیا ادا شدہ لائسنس خود بخود بحال کائناں تھی سڳدا؛ تُہاکوں %2$s تے Babilim سپورٹ نال رابطہ کرݨ پوسی۔ شناخت رکھݨ کیتے منسوخ دباؤ، ایں سائٹ دیاں Babilim ترتیباں وچ "ان انسٹال کرݨ تے Babilim دا سارا ڈیٹا مٹا ݙیوو" دا نشان ہٹاؤ، تے ولدا غیر فعال کرو۔ ہر حال وچ غیر فعال کروں؟' . "\0" . 'ایں نیٹ ورک تے %1$d سائٹاں ایں طرح سیٹ ہن جو پلگ ان مٹاونْ تے اپݨی Babilim شناخت مٹا ݙیون۔ پھر ایں سائٹاں نال جڑے ادا شدہ لائسنس خود بخود بحال کائناں تھی سڳدے؛ تُہاکوں %2$s تے Babilim سپورٹ نال رابطہ کرݨ پوسی۔ شناختاں رکھݨ کیتے منسوخ دباؤ، ہر سائٹ دیاں Babilim ترتیباں وچ "ان انسٹال کرݨ تے Babilim دا سارا ڈیٹا مٹا ݙیوو" دا نشان ہٹاؤ، تے ولدا غیر فعال کرو۔ ہر حال وچ غیر فعال کروں؟','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s کرݨ دی کوئی گال کائنی۔','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s۔ زبان چݨو۔','%d failed'=>'%d ناکام' . "\0" . '%d ناکام','%d not yet tried'=>'%d دی ہݨ تک کوشش کائنی تھئی' . "\0" . '%d دی ہݨ تک کوشش کائنی تھئی','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d رپورٹ انتظار کر رہی ہے۔ "Always share" تے "Don\'t share" سارئیں تے لاگو تھیندے ہن۔' . "\0" . '%d رپورٹاں انتظار کر رہیاں ہن۔ "Always share" تے "Don\'t share" سارئیں تے لاگو تھیندے ہن۔','%d skipped'=>'%d چھوڑے ڳئے' . "\0" . '%d چھوڑے ڳئے','%d succeeded'=>'%d کامیاب' . "\0" . '%d کامیاب','%d to install'=>'%d انسٹال کرݨ کیتے' . "\0" . '%d انسٹال کرݨ کیتے','(a public key generated for this site)'=>'(اس سائٹ کیتے بݨائی گئی پبلک کی)','(detected)'=>'(پتہ لگیا)','(generic codes and coordinates only)'=>'(صرف عام کوڈ تے کوآرڈینیٹس)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'%1$s تے صفائی روک ݙتی گئی: %2$s۔ کجھ وی ڈیلیٹ کائنی کیتا گیا۔','A file in the component could not be read, so it was not packaged.'=>'کمپوننٹ دی اک فائل پڑھی نہیں جا سکی، ایں کِیتے اوکوں پیک نہیں کیتا گیا۔','A host that serves only one PHP request at a time cannot complete this step.'=>'جیڑھا ہوسٹ اکو ویلے صرف اکو PHP درخواست سنبھالیندا ہے، او ایہ مرحلہ مکمل نہیں کر سگدا۔','A part of the upload kept failing, so the upload was cancelled.'=>'اپ لوڈ دا اکو حصہ بار بار ناکام ریہا، اس کیتے اپ لوڈ منسوخ کر ݙتا گیا۔','A translation cannot be requested for that locale on this site right now.'=>'ایں لوکیل کیتے ایں سائٹ تے ہݨ ترجمے دی درخواست نہیں کیتی ونڄ سڳدی۔','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'ترجمہ انڈیکس دی لکھائی %1$s تے ݙوجھی درخواست نال ٹکرا گئی (%2$s) تے لاگو نئیں تھئی؛ سب توں نواں ورژن رکھیا ڳیا۔','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'%1$s تے ترجمہ انڈیکس دی لکھائی (%2$s) مکمل نئیں تھی سڳی تے لاگو نئیں تھئی (%3$s)۔','Account'=>'اکاؤنٹ','Add another language'=>'ہک ہور زبان شامل کرو','Advanced'=>'ایڈوانس','All'=>'سارے','All free-plan slots for this site are used'=>'اس سائیٹ واسطے مفت پلان دے سارے سلاٹ ورتے ون ہوئے ہن','All languages'=>'ساریاں زباناں','Already in WordPress core'=>'پہلے ای WordPress کور وچ موجود ہے','Already installed.'=>'پہلے توں انسٹال ہے۔','Always share'=>'Always share','Another installation is running; try again in a moment.'=>'ہک ہور انسٹالیشن چل رہی ہے؛ تھوڑی دیر بعد دوبارہ کوشش کرو۔','Automatic installs'=>'آپوں آپ انسٹال','Automatic installs are now off; turn them on again in the settings if you want them.'=>'خودکار انسٹال ہݨ بند ہن؛ جے چاہو تاں ترتیباں وچ ولدا آن کر گھنو۔','Available'=>'دستیاب','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'دستیاب ترجمے اکو کلک نال انسٹال کیتے ونج سڳدے ہن تے گم شدہ ترجمیاں دی درخواست کیتی ونج سڳدی اے۔ جڈاں خودکار انسٹالیشناں چالو ہوون، تاں جہڑے ترجمے سروس تہاڈیاں منیجڈ زباناں واسطے دستیاب دسیندی اے اوہ روزانہ دو واری سنک دے دوران انسٹال تھی ویندے ہن۔','Available · %s'=>'دستیاب · %s','Babilim Settings'=>'Babilim ترتیباں','Babilim adds translations for every language checked here.'=>'Babilim ہیٹھ نشان زد ہر زبان کِیتے ترجمے شامل کریندا ہے۔','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim ویب سائٹ توں باہر کوئی عارضی فولڈر تصدیق نہیں کر سڳیا، ایں لئی جزو دا پیکیج نہیں بنیا تے کجھ وی اپ لوڈ نہیں تھیا۔ wp-config.php وچ BABILIM_TEMP_DIR کوں ویب روٹ توں باہر لکھن جوڳے فولڈر دے طور تے طے کرو (مثال دے طور تے تہاڈی سائٹ دی پبلک ڈائریکٹری دے اندر نہیں، بلکہ اوندے نال دا فولڈر)، یا اپنے ہوسٹ کولوں منگو۔','Babilim could not finish checking this site.'=>'Babilim ایں سائٹ دی چیکنگ مکمل نہیں کر سکیا۔','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim چالو کرݨ مکمل نہیں کر سگیا (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim ایں سائٹ دی تصدیق مکمل نہیں کر سڳیا (سروس واپس اتھاں تک نہیں پہنچ سڳی)۔ رجسٹریشن روکی ڳئی ہے۔','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim ایں سائٹ دی تصدیق نہیں کر سکیا، اس کیتے تصدیق کامیاب تھیݨ تک کجھ ڈاؤن لوڈ یا انسٹال نہیں تھیسی۔','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim ایس سائٹ دی تصدیق نہیں کر سگیا، ایں کیتے کجھ ڈاؤن لوڈ یا انسٹال نہیں کیتا ڳیا۔','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim ایں سائٹ تے اوہ پلگ ان تے تھیمز لبھیندا ہے جنہاں دا تہاݙی زبان وچ ترجمہ کائنی، تے ہر اکو کیتے اکو ترجمہ انسٹال کریندا ہے۔','Babilim has not been enabled for this site yet.'=>'Babilim ہݨ تائیں ایں سائٹ کیتے فعال کائنی کیتا ڳیا۔','Babilim has not installed any translation for this language.'=>'Babilim ایں زبان کیتے کوئی ترجمہ انسٹال کائناں کیتا۔','Babilim hit an error. Share an error report?'=>'Babilim وچ ایرر آ ڳیا۔ ایرر رپورٹ شیئر کرو؟','Babilim installed %d translation automatically since your last visit.'=>'تہاݙی پچھلی وزٹ توں بعد Babilim نے %d ترجمہ خودکار طور تے انسٹال کیتا۔' . "\0" . 'تہاݙی پچھلی وزٹ توں بعد Babilim نے %d ترجمے خودکار طور تے انسٹال کیتے۔','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim بند ہے۔ ہور کجھ نہیں ٻھیجیا ویسی؛ پہلے توں انسٹال کیتے ہوئے ترجمے کم کریندے رہسن۔','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim فعال ہے: ایہ سائٹ تصدیق شدہ ہے تے %d کمپوننٹ لبھیا ڳیا۔' . "\0" . 'Babilim فعال ہے: ایہ سائٹ تصدیق شدہ ہے تے %d کمپوننٹ لبھے ڳئے۔','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim ایں سائٹ کوں چالو تے چیک کر رہیا ہے… (آخری کوشش: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim ایں سائٹ کوں چالو تے چیک کر رہیا ہے… ایں ورقے کوں ریلوڈ کرو یا شیڈول چیک مکمل تھیوݨ دا انتظار کرو۔','Babilim is not enabled.'=>'Babilim فعال کائنی۔','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim ایں طرح سیٹ ہے جو پلگ ان مٹاونْ تے ایں سائٹ دی شناخت مٹا ݙیوے۔ پھر ایں سائٹ نال جڑیا ادا شدہ لائسنس خود بخود بحال کائناں تھی سڳدا؛ تُہاکوں %s تے Babilim سپورٹ نال رابطہ کرݨ پوسی۔ شناخت رکھݨ کیتے منسوخ دباؤ، Babilim ترتیباں وچ "ان انسٹال کرݨ تے Babilim دا سارا ڈیٹا مٹا ݙیوو" دا نشان ہٹاؤ، تے ولدا غیر فعال کرو۔ ہر حال وچ غیر فعال کروں؟','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim دا ایں مرحلے کیتے وقت مک گیا تے اگلی چیک تے جاری رکھسی۔','Babilim settings'=>'Babilim ترتیباں','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Babilim سنک سروس ولوں عارضی طور تے رُکی ہوئی ہے (ریٹ لمٹ)؛ اے %s توں بعد ول کوشش کرسی۔','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'اس اپ لوڈ دے انتظار دوران Babilim اپ ڈیٹ تھی گیا۔ پرانا پیکیج رد کر ݙتا گیا ہے؛ مہربانی کر کے اپ لوڈ دی دوبارہ تصدیق کرو۔','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim %1$s (ورژن %2$s) دیاں اے فائلاں اپ لوڈ کریسی: ہر .php تے .js فائل، ہر block.json فائل، تے اینکوں دے مین فولڈر وچ readme.txt، readme.md، style.css تے theme.json۔ اے او متن لبھن لئی تے پلگ ان یا تھیم دی شناخت کرن لئی ورتیاں ویندیاں ہن جنکوں ترجمے دی لوڑ ہے۔','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest مہیا نہیں اے: %s','Back'=>'واپس','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'کیا تُساں ایں ڈومین کِیتے پہلے لائسنس خریدیا ہئی؟ چیک آؤٹ ویلے ملیا ہویا بحالی کوڈ درج کرو۔','Broken placeholder'=>'ٹُٹا ہویا پلیس ہولڈر','Build'=>'بلڈ','Built'=>'تیار کیتا ڳیا','Bulk actions apply only to the selected language of each selected component.'=>'بلک ایکشنز ہر چݨے ہوئے کمپوننٹ دی صرف چݨی ہوئی زبان تے لاگو تھیندے ہن۔','Bulk actions apply to every matching language of each selected component.'=>'بلک ایکشنز ہر چݨے ہوئے کمپوننٹ دی ہر مطابق زبان تے لاگو تھیندے ہن۔','Bulk download:'=>'کٹھا ڈاؤن لوڈ:','Bulk request:'=>'کٹھی درخواست:','Bulk update:'=>'کٹھی اپ ڈیٹ:','Bundled with the plugin'=>'پلگ اِن نال شامل','Bundled with the theme'=>'تھیم نال شامل','By clicking Enable, you agree to send the information listed above to Babilim.'=>'چالو کرو تے کلک کرݨ نال تساں اُتے ݙتی ہوئی معلومات Babilim کوں ٻھیجݨ تے راضی تھیندے او۔','By continuing you confirm that you have the right to upload this component.'=>'جاری رکھݨ نال تusاں تصدیق کریندے ہو جو ایہ کمپوننٹ اپ لوڈ کرݨ دا تہاڈے کول حق ہے۔','Cancel'=>'منسوخ کرو','Category'=>'زمرہ','Check again'=>'ولدا چیک کرو','Check again now'=>'ہݨ ولدا چیک کرو','Checkout is not available for this site right now.'=>'ایں سائٹ کیتے چیک آؤٹ ہݨ دستیاب نہیں ہے۔','Choose'=>'چݨو','Choose a category…'=>'زمرہ چݨو…','Choose a language'=>'زبان چݨو','Choose a language…'=>'زبان چُݨو…','Clear filters'=>'فلٹر صاف کرو','Close'=>'بند کرو','Component'=>'کمپوننٹ','Confirm'=>'تصدیق کرو','Conflicting keys'=>'متصادم کیز','Continue'=>'جاری رکھو','Continue next batch (%d left)'=>'اڳلی کھیپ جاری رکھو (%d باقی)','Continuing…'=>'جاری ہے…','Could not back up %s before replacing it.'=>'%s کوں بدلݨ کنوں پہلے بیک اپ نہیں کر سڳے۔','Could not create the package archive.'=>'پیکیج آرکائیو نہیں بݨ سکیا۔','Could not determine active components; the existing merged index was left unchanged.'=>'فعال جزو دا پتہ کائنی لگ سگیا؛ موجودہ ضم شدہ انڈیکس کوں نہیں بدلیا گیا۔','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'انسٹال کیتے ہوئے پلگ ان/تھیم دا پتہ کائنی لگ سگیا؛ صفائی چھوڑ دتی گئی، کجھ وی کائنی مٹایا گیا۔','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'سروس کنوں WordPress.org دی پوری لوکیل فہرست لوڈ کائنی تھی سڳی، ایں کیتے ہݨ کوئی ہور زبان شامل کائنی کیتی ونڄ سڳدی۔','Could not move %s into place.'=>'%s کوں اپݨی جاہ تے نہیں رکھ سڳے۔','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'\'%s\' دی ضم شدہ فہرست مقررہ جاء تے منتقل نئیں کیتی ونڄ سگی؛ پچھلی ورتی ویندی فہرست (جے ہئی) اڌ ادھوری اپ ڈیٹ تھی ہوئی چھوڑݨ دی بجائے ہٹا ݙتی گئی۔ اڳلی کامیاب ری بلڈ تک ایں لوکیل کیتے کوئی ڈیفالٹ ڈومین سپلیمنٹ نئیں ݙتا ویسی۔','Could not open zip: %s'=>'zip کائنی کھولی ون٘ج سگی: %s','Could not prepare %s for rollback.'=>'%s نوں رول بیک کِیتے تیار نہیں کیتا جا سکیا۔','Could not read %s back after moving it into place.'=>'%s نوں جگہ تے رکھن توں بعد ولدا پڑھیا نہیں جا سکیا۔','Could not read: %s'=>'نہیں پڑھ سکیا: %s','Could not restore the purchase: %s'=>'خریداری بحال کائنی تھی سڳی: %s','Could not show a new restore code: %s'=>'نواں بحالی کوڈ کائنی ݙکھایا ونڄ سڳیا: %s','Could not stage %s'=>'%s سٹیج نہیں تھی سڳی','Could not stage default/%s'=>'default/%s سٹیج نہیں تھی سڳی','Could not start checkout: %s'=>'چیک آؤٹ شروع نہیں تھی سڳیا: %s','Could not verify entry count for %s'=>'%s واسطے اندراجاں دی گنتی دی تصدیق نہیں تھی سڳی','Could not write the downloaded package to disk.'=>'ڈاؤن لوڈ کیتا ہویا پیکیج ڈسک تے نہیں لکھیا ون٘ج سگیا۔','Could not write the staged merged index.'=>'تیار کیتی ہوئی ضم شدہ فہرست لکھی نئیں ونڄ سگی۔','Current translation'=>'موجودہ ترجمہ','Custom overrides'=>'حسب ضرورت اووررائیڈ','Danger zone'=>'خطرے دا علاقہ','Default supplement entry count mismatch.'=>'Default سپلیمنٹ دے اندراجاں دی گنتی نہیں ملدی۔','Delete all Babilim data on uninstall'=>'ان انسٹال کرݨ تے Babilim دا سارا ڈیٹا مٹا ݙیوو','Disable Babilim'=>'Babilim غیر فعال کرو','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Babilim غیر فعال کروں؟ انسٹال تھئے ترجمے رہ ویسن، پر اڳوں کوئی چیک یا ڈاؤن لوڈ کائنی تھیسی۔','Don\'t share'=>'Don\'t share','Download'=>'ڈاؤنلوڈ کرو','Downloaded and installed.'=>'ڈاؤن لوڈ تے انسٹال تھی گیا۔','Downloading…'=>'ڈاؤنلوڈ تھیندی پئی اے…','Downloads: %1$d/%2$d (%3$s)'=>'ڈاؤن لوڈ: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'ہر کمپوننٹ دا اپݨا حصہ ہر لوکیل دے سانجھے default-domain اضافے وچ۔','Enable Babilim'=>'Babilim فعال کرو','Enabling…'=>'چالو تھی رہیا ہے…','English (United States)'=>'English (United States)','Entries'=>'اندراجات','Entry count mismatch for %s'=>'%s واسطے اندراجاں دی گنتی نہیں ملدی','Error reports'=>'ایرر رپورٹاں','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'ہر انسٹال کیتا ہویا پلگ ان/تھیم: ایندا سلگ، ورژن، ٹیکسٹ ڈومین، ایہ WordPress.org تے درج اے کہ نئیں، ایندے اپݨے شامل لوکیلز، تے کیہڑے لوکیلز کیتے تساں پہلے توں Babilim ترجمہ انسٹال کیتا اے۔','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'ایں سائٹ تے ورتیا ویندا ہر لوکیل (سائٹ لوکیل، انسٹال کیتے ہوئے لینگویج پیک، صارف لوکیلز، تے جیڑھے تساں ہتھوں شامل کرو)۔ کوئی لوکیل کہیں ݙوجھے توں مختلف نئیں سمجھیا ویندا۔','Excluded'=>'خارج','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'ہور ناں یا ایکسٹینشن والیاں فائلاں شامل نہیں ہن، نہ ای uploads، cache، logs، backup، data، vendor، node_modules تے languages فولڈر، چھپیاں ہوئیاں فائلاں، یا اوہ فائلاں جنہاں دے ناں عام رازدار فائلاں نال ملدے ہن (wp-config*، .env*، *.sql، *.log، *.pem، *.key)۔ کوڈ فائلاں وچ ہجے وی اجیہا متن یا ڈیٹا ہو سڳدا ہے جیکوں تusی شیئر نہ کرنا چاہو؛ جے یقین نہ ہووے تاں انہاں کوں چیک کرو۔ سروس آمد تے انہاں ای قسماں دیاں فائلاں کوں دوبارہ ہٹا ݙیندی ہے۔','Free'=>'مفت','Free-plan slots'=>'مفت پلان دے سلاٹ','General'=>'عام','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'جے ایہ آن ہے تاں ان انسٹال کرݨ نال ایں سائٹ دی شناخت وی مٹ ویسی۔ ایں سائٹ نال جڑیا ادا شدہ لائسنس بعد وچ خود بخود بحال کائناں تھی سڳدا؛ اوکوں واپس گھنݨ کیتے تُہاکوں %s تے Babilim سپورٹ نال رابطہ کرݨ پوسی۔','Included'=>'شامل','Included in index'=>'فہرست وچ شامل','Install available translations automatically'=>'دستیاب ترجمے آپوں آپ انسٹال کرو','Installed'=>'انسٹال تھیا','Installed translations are kept, but no further checks or downloads will run.'=>'انسٹال کیتے ہوئے ترجمے رکھے ویندے ہن، پر اڳوں کوئی چیک یا ڈاؤن لوڈ نہیں تھیسی۔','Installed · %s'=>'انسٹال تھیا · %s','Installed · built for %1$s, this site has %2$s'=>'انسٹال تھیا ہویا · %1$s کیتے بݨایا ڳیا، ایں سائٹ تے %2$s ہے','Installed · built for %s'=>'انسٹال تھیا ہویا · %s کیتے بݨایا ڳیا','Installed · built for %s, all free-plan slots for this site are used'=>'انسٹال کیتا ہویا · %s واسطے بنایا گیا، اس سائیٹ واسطے مفت پلان دے سارے سلاٹ ورتے ون ہوئے ہن','Installed · built for %s, new version failed'=>'انسٹال تھیا · %s کیتے بݨایا ڳیا، نواں ورژن ناکام تھی ڳیا','Installed · built for %s, new version not covered by the free service plan'=>'انسٹال کیتا ہویا · %s واسطے بنایا گیا، نواں ورژن مفت سروس پلان وچ شامل کینی','Installed · built for %s, new version scheduled'=>'انسٹال تھی گیا · %s کیتے بݨایا گیا، نواں ورژن شیڈول کیتا گیا','Installed · built for %s, translating the new version…'=>'انسٹال تھیا ہویا · %s کیتے بݨایا ڳیا، نویں ورژن دا ترجمہ تھیندا پیا ہے…','Installed · built for a different version'=>'انسٹال تھیا ہویا · ہک ݙوجھے ورژن کیتے بݨایا ڳیا','Installed · built for a different version, all free-plan slots for this site are used'=>'انسٹال کیتا ہویا · مختلف ورژن واسطے بنایا گیا، اس سائیٹ واسطے مفت پلان دے سارے سلاٹ ورتے ون ہوئے ہن','Installed · built for a different version, new version failed'=>'انسٹال تھیا · کسے ہور ورژن کیتے بݨایا ڳیا، نواں ورژن ناکام تھی ڳیا','Installed · built for a different version, new version not covered by the free service plan'=>'انسٹال کیتا ہویا · مختلف ورژن واسطے بنایا گیا، نواں ورژن مفت سروس پلان وچ شامل کینی','Installed · built for a different version, new version scheduled'=>'انسٹال تھی گیا · مختلف ورژن کیتے بݨایا گیا، نواں ورژن شیڈول کیتا گیا','Installed · built for a different version, translating the new version…'=>'انسٹال تھیا ہویا · ہک ݙوجھے ورژن کیتے بݨایا ڳیا، نویں ورژن دا ترجمہ تھیندا پیا ہے…','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'ایہ سروس دے ہوسٹنگ پرووائیڈر کول محفوظ تھیندا ہے تے ترجمہ بݨاوݨ کیتے AI ماڈلز ایندی پروسیسنگ کریندے ہن۔','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'سب کجھ صاف کرݨ یا ایہ پلگ ان ان انسٹال کرݨ ویلے میڈے اپݨے ترجمے دے اووررائیڈ رکھو۔','Language'=>'زبان','Language:'=>'زبان:','Languages'=>'زباناں','Languages found on this site: %s.'=>'ایں سائٹ تے ملیاں زباناں: %s۔','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'آخری صفائی %1$s تے تھی: %2$d نویں نشان زد کیتیاں گیاں، %3$d فائل مٹائیاں گیاں، %4$d ریکارڈ ہٹائے گئے۔','Maintenance'=>'دیکھ بھال','Maintenance status is not available right now.'=>'دیکھ بھال دی حالت ہݨے دستیاب کائنی۔','Manifest unavailable: %s'=>'مینی فیسٹ دستیاب کائنی: %s','Negation reversed'=>'نفی اُلٹ ڳئی','No'=>'نہیں','No build is available to download for this locale.'=>'ایں لوکیل کیتے ڈاؤن لوڈ کرݨ کیتے کوئی بلڈ دستیاب کائناں۔','No cleanup has run yet.'=>'ہݨ تئیں کوئی صفائی نئیں تھئی۔','No components match these filters. %s'=>'کوئی جزو ایں فلٹراں نال نہیں ملدا۔ %s','No components synced yet.'=>'ہݨ تک کوئی جزو سنک کائنی تھیا۔','No installed translation matches.'=>'کوئی انسٹال کیتا ہویا ترجمہ میل کائناں کھاندا۔','No language is managed yet.'=>'ہݨ تائیں کوئی زبان منیج کائنی تھیندی۔','No pending challenge for this nonce.'=>'اس nonce کِیتے کوئی زیر التوا چیلنج نہیں۔','No pending challenge to verify.'=>'تصدیق کیتے کوئی زیر التوا چیلنج نہیں۔','No plugins or themes found.'=>'کوئی پلگ اِن یا تھیم کینہ لبھی۔','No previous build to roll back to.'=>'رول بیک کرن کِیتے کوئی پچھلی بلڈ نہیں۔','No record for %s'=>'%s واسطے کوئی ریکارڈ کائنی','No site id is on file to rotate a token for.'=>'ٹوکن بدلݨ کیتے کوئی سائٹ آئی ڈی فائل وچ محفوظ نہیں۔','No — component inactive'=>'نہیں — کمپوننٹ غیر فعال ہے','No — component removed'=>'نہیں — کمپوننٹ ہٹا ݙتا ڳیا','No — installed version differs from the active one'=>'نہیں — انسٹال کیتا ہویا ورژن فعال ورژن کنوں مختلف ہے','Not a valid server_build_id: %s'=>'درست server_build_id کائنی: %s','Not covered by the free service plan'=>'مفت سروس پلان وچ شامل کینی','Not installed'=>'انسٹال کینی','Not registered yet'=>'ہݨ تائیں رجسٹر کائنی','Not supported'=>'سپورٹ نئیں کیتا ڳیا','Not verified'=>'تصدیق کائنی تھئی','Note (optional)'=>'نوٹ (اختیاری)','Nothing to choose.'=>'چݨݨ کیتے کجھ کائنی۔','Nothing to confirm.'=>'تصدیق کیتے کجھ کائنی۔','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'پہلے کنوں بند: پلگ ان مٹاوݨ نال ایں سائٹ دی شناخت رکھی ویندی ہے، تاں جو دوبارہ انسٹال کرن تے اوہو ورتی ونڄ سڳے۔','One or more served files no longer match the manifest.'=>'اک یا ودھ فائلاں ہُن مینی فیسٹ نال نہیں ملدیاں۔','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'ایں سائٹ کِیتے اکو واری خریداری: %1$s %2$s۔ ایندے وچ ترجمے دیاں سبھ آوݨ آلیاں اپ ڈیٹس شامل ہن۔ ادائیگی Paddle ولوں نویں ٹیب وچ کیتیویندی ہے۔','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'صرف نیٹ ورک ایڈمنسٹریٹر ایہ کم کر سڳدا ہے، کیوں جو ایہ ترجمے دیاں اوہ فائلاں بدلیندا ہے جیڑھیاں ایں نیٹ ورک دیاں ساریاں سائٹاں وچ سانجھیاں ہن۔','Only plugins and themes can be packaged.'=>'صرف پلگ اِن تے تھیم پیکیج کیتے ونج سکدے ہن۔','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'صرف تݙاں جݙاں تusی کسے ایجھے پلگ ان یا تھیم واسطے اپ لوڈ دی تصدیق کرو جیڑھا WordPress.org تے نہیں ہے: ہر .php تے .js فائل، ہر block.json فائل، تے اس جزو دے مین فولڈر وچ readme.txt، readme.md، style.css تے theme.json، zip دی شکل وچ، عام رازدار فائلاں چھوڑن دے بعد۔','Open Babilim settings'=>'Babilim ترتیباں کھولو','Original language'=>'اصلی زبان','Original string'=>'اصلی سٹرنگ','Paid'=>'ادائیگی والا','Partner'=>'پارٹنر','Please check that your site can be reached from the internet, then try again.'=>'مہربانی کر کے چیک کرو جو تہاݙی سائٹ انٹرنیٹ توں پہنچ وچ ہے، فیر ݙوبارہ کوشش کرو۔','Please choose a category for this report.'=>'مہربانی کر تے ایں رپورٹ کیتے زمرہ چݨو۔','Plugin'=>'پلگ اِن','Plugin · %s'=>'پلگ اِن · %s','Plugins'=>'پلگ اِن','Preview'=>'پیش نظارہ','Purchase restored. This site is now licensed.'=>'خریداری بحال تھی گئی۔ ہݨ اے سائٹ لائسنس یافتہ ہے۔','Re-parsed entry count did not match the built index.'=>'دوبارہ پارس کیتی گئی اندراجات دی گݨتی بݨائے گئے انڈیکس نال میل کائنی کھاندی۔','Re-verify'=>'ݙوبارہ تصدیق کرو','Rebuild index now'=>'ہݨ انڈیکس ݙوبارہ بݨاؤ','Refusing to write outside the Babilim language-file directory.'=>'Babilim دی زبان فائل ڈائریکٹری توں باہر لکھݨ توں انکار۔','Registration response was missing required fields.'=>'رجسٹریشن دے جواب وچ ضروری خانے غائب ہن۔','Registration restarted.'=>'رجسٹریشن ولدا شروع کر ݙتی ڳئی۔','Remove'=>'ہٹاؤ','Remove everything Babilim installed'=>'Babilim دا انسٹال کیتا ہر کجھ ہٹاؤ','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Babilim دا انسٹال کیتا ہر کجھ ہٹاؤ؟ ایہ اس سائٹ تے ہر پلگ اِن تے تھیم کیتے Babilim دیاں انسٹال کیتیاں ہوئیاں ساریاں زبان فائلاں مٹا ݙیسی۔','Remove the %2$s translation of %1$s from this site?'=>'کیا %1$s دا %2$s وچ ترجمہ ایں سائٹ توں ہٹاوݨا اے؟','Removed %d installed component.'=>'%d انسٹال شدہ کمپوننٹ ہٹا ݙتا ڳیا۔' . "\0" . '%d انسٹال شدہ کمپوننٹ ہٹا ݙتے ڳئے۔','Removed after a failed integrity check'=>'سالمیت دی جانچ ناکام تھیݨ دے بعد ہٹا ݙتا گیا','Removed.'=>'ہٹا ݙتا ڳیا۔','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'اس سائٹ تے ہر پلگ اِن تے تھیم کیتے Babilim دیاں انسٹال کیتیاں ہوئیاں ساریاں زبان فائلاں ہٹیندا ہے۔','Report a problem'=>'مسئلے دی رپورٹ کرو','Report translation'=>'ترجمے دی رپورٹ کرو','Request newer translation'=>'نویں ترجمے دی درخواست کرو','Request translation'=>'ترجمے دی درخواست کرو','Requestable'=>'درخواست دے قابل','Requesting…'=>'درخواست تھیندی پئی اے…','Restart registration'=>'رجسٹریشن دوبارہ شروع کرو','Restore code'=>'بحالی کوڈ','Restore purchase'=>'خریداری بحال کرو','Retry request'=>'درخواست ولدا کرو','Roll back'=>'پچھلی حالت تے ولو','Roll back and report'=>'پچھلی حالت تے ولو تے رپورٹ کرو','Roll back and send report'=>'پچھلی حالت تے ولو تے رپورٹ بھیجو','Roll back the %2$s translation of %1$s to the previous build?'=>'کیا %1$s دا %2$s وچ ترجمہ پچھلے بلڈ تے واپس کرݨا اے؟','Rolled back and reported.'=>'پچھلے بلڈ تے واپس کر ݙتا ڳیا تے رپورٹ وی بھیج ݙتی ڳئی۔','Rolled back to the previous build.'=>'پچھلے بلڈ تے واپس ونڄ ڳیا۔','Rolled back, but the report could not be sent: %s'=>'واپس ونڄ ڳیا، پر رپورٹ کائنی بھیجی ونڄ سگی: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'رول بیک نال \'%1$s\' (%2$s) اوور رائٹ ہو ویسی، جیڑھی ہُن کسے ہور انسٹال کیتے ہوئے کمپوننٹ (%3$s) کِیتے مہیا کیتی ویندی پئی اے؛ کجھ وی تبدیل نہیں کیتا گیا۔','Rotate-token response was missing site_token.'=>'ٹوکن بدلݨ دے جواب وچ site_token غائب ہئی۔','Save changes'=>'تبدیلیاں محفوظ کرو','Scheduled, waiting to be processed'=>'شیڈول کیتا ڳیا، کارروائی دا انتظار ہے','Search'=>'ڳولو','Search components'=>'جزو تلاش کرو','Search the installed translations'=>'انسٹال کیتے ہوئے ترجمے ڳولو','Select all'=>'سارے چݨو','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'گھٹ جزو چݨو: ہر دور وچ وڈھ توں وڈھ %1$d کارروائیاں ہو سگدیاں ہن (تساں %2$d چݨے ہن)۔','Send report'=>'رپورٹ بھیجو','Service plan'=>'سروس پلان','Settings'=>'ترتیباں','Share error reports'=>'ایرر رپورٹاں شیئر کرو','Share this report'=>'ایہ رپورٹ شیئر کرو','Show a new restore code'=>'نواں بحالی کوڈ ݙکھاؤ','Show the "Report translation" entry in the admin toolbar'=>'ایڈمن ٹول بار وچ "ترجمہ دی رپورٹ کرو" اندراج ڈکھاؤ','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'ایں کمپوننٹ دا کجھ متن ایندے مصنف ہارڈ کوڈ کیتا ہے تے زبان پیک نال ایندا ترجمہ کائنی تھی سڳدا۔','Status'=>'حالت','Status unknown'=>'حالت نامعلوم','String context'=>'سٹرنگ دا سیاق','Suggested translation'=>'تجویز کیتا ہویا ترجمہ','Supplementary translation index'=>'اضافی ترجمیاں دی فہرست','Supplementary translation index rebuilt.'=>'اضافی ترجمیاں دی فہرست ولدا بݨا ݙتی ڳئی۔','Supplementary translation maintenance'=>'اضافی ترجمے دی دیکھ بھال','Supplementary translations'=>'اضافی ترجمے','Sweep aborted without orphaning anything: %s.'=>'کہیں کوں یتیم کیتے بغیر صفائی روک ݙتی گئی: %s۔','Sweep complete: %d file deleted.'=>'سکین مکمل تھی گیا: %d فائل مٹائی ڳئی۔' . "\0" . 'سکین مکمل تھی گیا: %d فائلاں مٹائیاں ڳیاں۔','Sweep now'=>'هݨ سکین کرو','Sync complete.'=>'سنک مکمل تھی ڳیا۔','Thank you. Your report was sent.'=>'شکریہ۔ تہاݙی رپورٹ بھیج ݙتی ڳئی۔','That component is not installed on this site, so a translation cannot be requested for it.'=>'ایہ کمپوننٹ اس سائٹ تے انسٹال کائناں، ایâس کرکے ایندے کیتے ترجمہ دی درخواست نہیں کیتی ونڄ سڳدی۔','That does not look like a restore code.'=>'اے بحالی کوڈ دے طور تے ٹھیک کائنی لگدا۔','That is not a valid WordPress locale code. Nothing was saved.'=>'ایہ WordPress دا درست لوکیل کوڈ کائناں۔ کجھ محفوظ کائناں کیتا ڳیا۔','That is not a valid build identifier.'=>'ایہ درست بلڈ شناخت کار کائنی۔','The change could not be recorded in the translation index; please try again.'=>'تبدیلی ترجمیاں دی فہرست وچ درج نہیں ہو سکی؛ مہربانی کر کے ولدا کوشش کرو۔','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'صفائی تھی گئی، پر کجھ تبدیلیاں ترجمیاں دی فہرست وچ درج نئیں تھی سگیاں؛ اڳلی صفائی وچ انہاں کوں درج کرݨ دی ولدا کوشش کیتی ویسی۔','The component has no files that can be uploaded.'=>'اس جزو وچ اپ لوڈ کرن جوڳیاں کوئی فائلاں نہیں ہن۔','The component is not inside the plugins or themes directory.'=>'کمپوننٹ پلگ اِن یا تھیم ڈائریکٹری دے اندر نہیں اے۔','The component\'s main file was not found.'=>'کمپوننٹ دی مین فائل نہیں لبھی۔','The download response was missing a usable location.'=>'ڈاؤن لوڈ دے جواب وچ کوئی قابل استعمال مقام نہیں ہا۔','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'ایہ اندراج اکو پینل کھولدا اے جتھے Babilim دے اس سائیٹ تے انسٹال کیتے ہوئے ترجمے لبھے ونج سڳدے ہن تے اوندے وچوں کہیں دی رپورٹ کیتی ونج سڳدی اے۔','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'خانہ "%1$s" بہوں لمبا ہے: اینکوں %2$d حرف ہن تے حد %3$d ہے۔ کجھ نئیں بھیجیا ڳیا؛ مہربانی کر تے اینکوں چھوٹا کرو تے ول کوشش کرو۔','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'دِتا گیا ڈومین \'%1$s\' نہ تاں پیکیج مینی فیسٹ دے اپنے سلگ \'%2$s\' نال ملدا اے تے نہ ای اوندے text_domain \'%3$s\' نال۔','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'\'%s\' دی ضم شدہ فہرست ولدی بݨائی گئی، پر ترجمیاں دی فہرست اینکوں درج نئیں کر سگی؛ اڳلی ری بلڈ ولدا کوشش کرسی۔','The original text and the translations made from it will be provided to other sites that install the same version.'=>'اصلی متن تے ایندے توں بݨے ترجمے ہوراں سائٹاں کوں مہیا کیتے ویسن جہڑیاں اے ای ورژن انسٹال کریندیاں ہن۔','The package declares no main translation file.'=>'پیکیج وچ کوئی مکھ ترجمے دی فائل ظاہر کائنی کیتی ڳئی۔','The package has no %s for its own text domain.'=>'پیکیج وچ اوندے اپنے ٹیکسٹ ڈومین کِیتے کوئی %s نہیں۔','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'پیکیج مینی فیسٹ دی قسم \'%1$s\' درخواست کیتی قسم \'%2$s\' نال میل نئیں کھاندی۔','The package produced no servable main translation file.'=>'پیکیج کنوں کوئی قابل پیش مکھ ترجمے دی فائل نہیں بݨی۔','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'پیکیج دا ٹیکسٹ ڈومین \'%1$s\' اس سائٹ دی کمپوننٹ دی کاپی (\'%2$s\') نال نہیں ملدا، ایں کِیتے اے انسٹال نہیں کیتا گیا۔','The packaged component could not be read.'=>'پیک کیتا ہویا کمپوننٹ پڑھیا نہیں جا سکیا۔','The registration challenge is not in the expected form.'=>'رجسٹریشن چیلنج متوقع شکل وچ کائنی۔','The report could not be sent.'=>'رپورٹ کائناں بھیجی ونڄ سڳی۔','The search could not be completed.'=>'ڳولݨ مکمل کائناں تھی سڳیا۔','The service asked this site to wait before syncing again.'=>'سروس نے اس سائٹ کوں آکھیا کہ ولدا سنک کرن توں پہلے انتظار کرے۔','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'سروس تُہاݙی سائٹ تائیں نہ پہنچ سگی۔ شاید فائر وال، سکیورٹی پلگ ان یا ہوسٹ دا کوئی اصول درخواست روک ریہا ہے؛ مہربانی کرکے /wp-json/babilim/v1/challenge تے درخواستاں دی اجازت ݙیوو۔','The service\'s upload offer was incomplete.'=>'سروس دی اپ لوڈ پیشکش ادھوری ہئی۔','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'ٹیکسٹ ڈومین \'%1$s\' (%2$s) پہلے ای کسے ہور انسٹال کیتے ہوئے کمپوننٹ (%3$s) کِیتے مہیا کیتا ویندا پیا اے؛ کجھ وی انسٹال نہیں کیتا گیا۔','The upload is kept until you ask Babilim to delete it.'=>'اپ لوڈ تیں تئیں رکھیا ویندا ہے جیں تئیں تساں Babilim کوں اونکوں مٹاوݨ دا نہ آکھو۔','Theme'=>'تھیم','Theme · %s'=>'تھیم · %s','Themes'=>'تھیم','There is no upload in progress.'=>'کوئی اپ لوڈ جاری کائنی۔','There is no upload waiting for confirmation.'=>'کوئی اپ لوڈ تصدیق دا منتظر کائنی۔','These are the languages this site uses. You can change them in %s.'=>'ایہ او زباناں ہن جہڑیاں ایہ سائٹ ورتیندی ہے۔ تساں انہاں کوں %s وچ بدل سگدے ہو۔','These fields will be sent:'=>'ایہ خانے بھیجے ویسن:','This build is not one this site currently knows about for this component/locale.'=>'ایہ بلڈ ایں کمپوننٹ/لوکیل کیتے ایں سائٹ دے معلوم بلڈاں وچ شامل کائناں۔','This component does not declare a version number, so a translation cannot be requested for it.'=>'ایہ کمپوننٹ ورژن نمبر ظاہر کائناں کریندا، ایâس کرکے ایندے کیتے ترجمے دی درخواست نہیں کیتی ونڄ سڳدی۔','This component is larger than the service accepts, so it cannot be uploaded.'=>'اے کمپوننٹ سروس دی قبول کرن دی حد توں وڈا اے، ایں کِیتے اپ لوڈ نہیں ہو سکدا۔','This component was already uploaded. Babilim is checking it now.'=>'ایہ کمپوننٹ پہلے ہی اپ لوڈ تھی ڳیا ہے۔ Babilim ہݨ ایکوں چیک کریندا پئے۔','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'ایں کمپوننٹ دا ورژن نمبر %d حرفاں کنوں ودھ لما ہے، جہڑا Babilim سنبھال کائناں سڳدا، ایâس کرکے ایندے کیتے ترجمے دی درخواست نہیں کیتی ونڄ سڳدی۔','This issues a new restore code and the previous one stops working. Continue?'=>'ایں نال نواں بحالی کوڈ جاری تھیسی تے پچھلا کوڈ کم کرݨ چھوڑ ڈیسی۔ جاری رکھو؟','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'ایں نیٹ ورک وچ سائٹاں ڈھیر ہن، ہک ہک کرکے چیک کائناں کیتیاں ونڄ سڳدیاں، تے کجھ سائٹاں شاید ایں طرح سیٹ ہوون جو پلگ ان مٹاونْ تے اپݨی Babilim شناخت مٹا ݙیون۔ ایجھی سائٹ نال جڑیا ادا شدہ لائسنس خود بخود بحال کائناں تھی سڳدا؛ تُہاکوں %s تے Babilim سپورٹ نال رابطہ کرݨ پوسی۔ شناختاں رکھݨ کیتے منسوخ دباؤ، ہر سائٹ دیاں Babilim ترتیباں وچ "ان انسٹال کرݨ تے Babilim دا سارا ڈیٹا مٹا ݙیوو" دا نشان ہٹاؤ، تے ولدا غیر فعال کرو۔ ہر حال وچ غیر فعال کروں؟','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'اس پلگ ان دا اپنا ورژن، تاں جو جے اے بہوں پرانا ہووے تے سروس تہانکوں اپ ڈیٹ کرݨ دا آکھ سگے۔','This report does not name a valid plugin or theme and locale.'=>'ایں رپورٹ وچ کوئی درست پلگ ان یا تھیم تے لوکیل دا ناں کائناں۔','This report does not name an installed string.'=>'اس رپورٹ وچ کسے انسٹال کیتی ہوئی سٹرنگ دا ناں نہیں ہے۔','This report is missing a valid build to report against.'=>'ایں رپورٹ وچ رپورٹ کرݨ کیتے درست بلڈ موجود کائنی۔','This report will be posted publicly on GitHub and may be kept by third parties.'=>'ایہ رپورٹ GitHub تے عوامی طور تے پوسٹ کیتی ویسی تے تیجی پارٹیاں اینکوں رکھ سڳدیاں ہن۔','This restore code was not recognised for this site.'=>'اے بحالی کوڈ ایں سائٹ کِیتے پچھاتا کائنی گیا۔','This site already has an active registration that can no longer be recovered automatically.'=>'ایں سائٹ دی پہلے کنوں فعال رجسٹریشن موجود ہے جیڑھی ہݨ خودکار طور تے بحال نہیں تھی سڳدی۔','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'اس سائٹ دے %1$d کمپوننٹ %2$d زباناں وچ ہن، جنہاں کِیتے %3$d چیک بیچ چاہیدے ہن؛ Babilim اک رن وچ زیادہ توں زیادہ %4$d سنبھال سکدا اے۔ ترتیباں وچ منیج کیتیاں زباناں گھٹاؤ یا غیر استعمال شدہ پلگ اِن تے تھیم ڈی ایکٹیویٹ کرو، فیر ہُنے ولدا چیک کرو دباؤ۔','This site has no purchase to show a code for.'=>'ایں سائٹ دی کوئی خریداری کائنی جیندا کوڈ ݙکھایا ونڄے۔','This site is already licensed. Reload the page.'=>'ایہ سائٹ پہلے کنوں لائسنس یافتہ ہے۔ ورقہ دوبارہ لوڈ کرو۔','This site is not registered with Babilim yet.'=>'ایہ سائٹ ہݨ تک Babilim نال رجسٹرڈ نہیں ہے۔','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'ایہ سائٹ اوں سائز کولوں وݙی ہے جیڑھا سروس اکو سنک وچ قبول کرین‌دی ہے، ایں کیتے کجھ آئٹم چھوڑ ݙتے ڳئے: %1$d جزو تے %2$d لوکیلز۔','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'ایہ سائٹ ملٹی سائٹ نیٹ ورک دا حصہ ہے، جیڑھا نوے ترجمے خودکار طور تے انسٹال نہیں کریندا۔ جیڑھے ترجمے پہلے کنوں انسٹال ہن اوہ ہݨ وی اپڈیٹ تھیندے ہن۔','This site is verified.'=>'ایں سائٹ دی تصدیق تھی ڳئی ہے۔','This site must be verified first.'=>'پہلے ایں سائٹ دی تصدیق ضروری ہے۔','This site\'s URL, so the service can verify you own it.'=>'اس سائٹ دا URL، تاں جو سروس تصدیق کر سگے جو اے تہاڈی ہے۔','This site\'s address is too long for Babilim to register.'=>'ایں سائٹ دا پتہ Babilim دے رجسٹر کرݨ کیتے بہوں لمبا ہے۔','This site\'s configured locale.'=>'ایں سائٹ دا ترتیب ݙتا ہویا لوکیل۔','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'اس سائٹ دی انسٹال پبلک کی، جیہڑی ثابت کرݨ کیتے ورتی ویندی ہے جو درخواستاں سچ مچ اس سائٹ توں آندیاں ہن۔ صرف پبلک حصہ ای بھیجیا ویندا ہے۔','This site\'s locale code is not one Babilim can register.'=>'اس سائٹ دا لوکیل کوڈ اوہ نہیں جیڑھا Babilim رجسٹر کر سکے۔','This string can\'t be reported from this site.'=>'ایہ سٹرنگ ایں سائٹ توں رپورٹ کائناں تھی سڳدی۔','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'اے سٹرنگ اس سائٹ تے انسٹال کیتے ہوئے ترجمیاں وچ شامل نہیں ہے۔ دوبارہ تلاش کرو تے لسٹ وچوں اینکوں چنو۔','This translation was updated since you searched. Search again and pick the string from the new list.'=>'تہاڈی تلاش دے بعد اے ترجمہ اپ ڈیٹ تھی گیا ہے۔ دوبارہ تلاش کرو تے نویں لسٹ وچوں سٹرنگ چنو۔','To translate this component, Babilim needs its source.'=>'ایہ کمپوننٹ دا ترجمہ کرݨ کیتے Babilim کوں ایندا سورس چاہیدا ہے۔','Too many attempts. Try again tomorrow.'=>'بہوں کوششاں تھی گیاں۔ کل ولدی کوشش کرو۔','Too many reports today. Try again tomorrow.'=>'اڄ بہوں ساریاں رپورٹاں تھی ڳیاں ہن۔ کل ولدا کوشش کرو۔','Too many requests.'=>'بہوں زیادہ درخواستاں۔','Toolbar'=>'ٹول بار','Translating…'=>'ترجمہ تھیندا پیا ہے…','Translation does not load'=>'ترجمہ لوڈ کائنی تھیندا','Translation failed'=>'ترجمہ ناکام تھی گیا','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'جیڑھیاں ترجمے دیاں فائلاں تسی %s وچ رکھو او ہمیشہ Babilim دیاں فائلاں کنوں ودھ ترجیح رکھیندیاں ہن۔ جیں تائیں تسی ایہ نشان نہ ہٹاوو، اے رکھیاں ویندیاں ہن۔','Translation requested.'=>'ترجمے دی درخواست کر ݙتی ڳئی۔','Translations'=>'ترجمے','Type'=>'قسم','Type at least 2 characters to search.'=>'ڳولݨ کیتے گھٹ توں گھٹ 2 حرف ٹائپ کرو۔','Unexpected HTTP %d response.'=>'غیر متوقع HTTP %d جواب۔','Uninstall'=>'ان انسٹال','Unknown kind: %s'=>'اݨ جاݨی kind: %s','Unsafe domain: %s'=>'غیر محفوظ ڈومین: %s','Unsafe locale: %s'=>'غیر محفوظ لوکیل: %s','Unsafe slug: %s'=>'غیر محفوظ سلگ: %s','Unsafe text_domain: %s'=>'غیر محفوظ text_domain: %s','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'بیس تک زیر التوا تشخیصی واقعات (مثلاً اوہ فائل جیڑھی سالمیت دی جانچ وچ ناکام تھئی)، ہر ہک وچ صرف کوڈ، کمپوننٹ تے لوکیل، تے کݙاہیں وی کوئی سٹرنگ مواد یا ترجمہ شدہ ٹیکسٹ نئیں۔','Update'=>'اپڈیٹ کرو','Update available'=>'اپ ڈیٹ دستیاب ہے','Updates'=>'اپڈیٹاں','Updating…'=>'اپڈیٹ تھیندی پئی اے…','Upgrade this site'=>'ایں سائٹ کوں اپ گریڈ کرو','Upload and request'=>'اپ لوڈ کرو تے درخواست کرو','Upload cancelled.'=>'اپ لوڈ منسوخ کر ݙتا ڳیا۔','Upload complete — translation requested.'=>'اپ لوڈ مکمل تھی ڳیا — ترجمے دی درخواست کر ݙتی ڳئی۔','Upload expired before it finished'=>'اپ لوڈ مکݨ توں پہلے ای ختم تھی گیا','Upload in progress — continue or cancel'=>'اپ لوڈ جاری ہے — جاری رکھو یا منسوخ کرو','Upload this component?'=>'ایہ کمپوننٹ اپ لوڈ کروں؟','Upload was not accepted'=>'اپ لوڈ قبول نئیں تھیا','Uploading'=>'اپ لوڈ تھیندا پئے','Uploading part %1$d of %2$d…'=>'حصہ %1$d از %2$d اپ لوڈ تھیندا پئے…','Uploading…'=>'اپ لوڈ تھیندا پئے…','Verified'=>'تصدیق تھی گئی','Verify response was missing site_token.'=>'تصدیق دے جواب وچ site_token غائب ہئی۔','Version %s'=>'ورژن %s','What is sent when Babilim checks this site'=>'جݙاں Babilim ایں سائٹ دی جانچ کریندا ہے تاں کیا بھیجیا ویندا ہے','What is sent when you enable Babilim'=>'Babilim فعال کرݨ تے کیا کجھ بھیجیا ویندا ہے','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'جݙاں Babilim دے اندر کجھ ناکام تھیندا ہے تاں Babilim سروس کوں ایرر رپورٹ بھیجو تاں جو اینکوں GitHub تے عوامی مسئلے دے طور تے شائع کیتا ونڄ سڳے۔ رپورٹ ایں سائٹ دی طرفوں بھیجی ویندی ہے، اوہو تصدیق نال جیڑھی Babilim سروس کوں ہر دوجی درخواست وچ ہوندی ہے۔ سروس صرف ایرر کوڈ تے ورژن GitHub تے عوامی مسئلے دے طور تے شائع کریندی ہے؛ عوامی مسئلے وچ سائٹ دا پتہ، مواد یا فائل پاتھ نہیں ہوندے۔ ڈیفالٹ طور تے بند ہے۔','Where you saw this (optional)'=>'تساں اے کتھاں ݙٹھا (اختیاری)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'جڈاں تئیں ایہ چالو اے، جہڑے ترجمے سروس تہاڈیاں منیجڈ زباناں واسطے دستیاب دسیندی اے اوہ روزانہ دو واری سنک دے دوران انسٹال تھی ویندے ہن۔','WordPress.org'=>'WordPress.org','Wrong for this context'=>'ایں سیاق کیتے غلط','Wrong meaning'=>'غلط مطلب','Wrong plural form'=>'غلط جمع شکل','Wrong term'=>'غلط اصطلاح','Yes'=>'ہاں','You are not allowed to do this.'=>'تہانوں اے کم کرݨ دی اجازت کائنی۔','Your PHP version, for compatibility.'=>'تہاڈا PHP ورژن، موافقت کیتے۔','Your WordPress version, to serve compatible translation files.'=>'تہاڈا WordPress ورژن، تاں جو موافق ترجمہ فائلاں مہیا کیتیاں ونجن۔','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'تہاڈا نواں بحالی کوڈ: %s۔ ایکوں کہیں محفوظ جاہ تے رکھو — پچھلا کوڈ ہݨ کم کائنی کریندا۔','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'تہاݙی رپورٹ AI ماڈلز ولوں خودکار طور تے پروسیس کیتی ویندی ہے تے دوجیاں سائٹاں کیتے ایں ترجمے کوں بہتر بݨا سڳدی ہے۔','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'تُہاݙی سائٹ نے جواب تاں ݙتا، پر متوقع جواب کائناں ہئی۔ ہو سڳدا ہے REST API کہیں ہور پلگ ان نے بدل ݙتی ہووے، یا او اینڈ پوائنٹ کیش تھیا ہووے؛ مہربانی کرکے /wp-json/babilim/v1/challenge کوں کیشنگ تے ری رائٹنگ کنوں الگ رکھو۔','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'تہاݙی سائٹ نے جواب ݙیݨ وچ بہوں دیر لائی۔ مہربانی کر کے بعد وچ ݙوبارہ کوشش کرو، تے چیک کرو جو تہاݙا ہوسٹ بہوں سست یا اوورلوڈ تاں کائنی۔','Zip has no manifest.json.'=>'زپ وچ manifest.json کائنی۔','Zip is missing expected default file: %s'=>'زپ وچ متوقع default فائل گم ہے: %s','Zip is missing expected file: %s'=>'زپ وچ متوقع فائل گم ہے: %s','_manifest.json has an unexpected structure'=>'_manifest.json دا ڈھانچہ غیر متوقع ہے','could not read _manifest.json: %s'=>'_manifest.json نہیں پڑھ سڳے: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest وچ \'%s\' غائب اے یا غلط اے۔','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'expected_manifest دا \'server_build_id\' درست بلڈ آئی ڈی نہیں۔','failed to parse _manifest.json: %s'=>'_manifest.json دا پارس کرݨ ناکام ریہا: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'ایہ %2$d منظم کمپوننٹس وچوں %1$d کوں یتیم کر ݙیسی (اڌ توں ڈھیر)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'ایہ ہر منظم %1$s کمپوننٹ کوں یتیم کر ݙیسی (%2$d وچوں %2$d)','l10n.php entry count mismatch for %s'=>'%s کِیتے l10n.php انٹریاں دی گنتی بے میل','manifest.json has an invalid \'default_domain_entries\'.'=>'manifest.json وچ \'default_domain_entries\' غلط اے۔','manifest.json has an invalid \'default_domain_files\'.'=>'manifest.json وچ \'default_domain_files\' غلط اے۔','manifest.json in the zip is not valid JSON.'=>'زپ وچ manifest.json درست JSON کائنی۔','manifest.json is missing or has an invalid \'%s\'.'=>'manifest.json وچ \'%s\' غائب اے یا غلط اے۔','manifest.json is missing or has an invalid \'build_no\'.'=>'manifest.json وچ \'build_no\' غائب اے یا غلط اے۔','manifest.json is missing or has an invalid \'entries\'.'=>'manifest.json وچ \'entries\' غائب اے یا غلط اے۔','manifest.json is missing or has an invalid \'extra_domains\'.'=>'manifest.json وچ \'extra_domains\' غائب اے یا غلط اے۔','manifest.json is missing or has an invalid \'files\'.'=>'manifest.json وچ \'files\' غائب اے یا غلط اے۔','manifest.json\'s \'%s\' does not match the expected value.'=>'manifest.json دا \'%s\' متوقع قدر نال میل نئیں کھاندا۔','manifest.json\'s \'contract\' is not a valid version string.'=>'manifest.json دا \'contract\' درست ورژن سٹرنگ نہیں۔','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'manifest.json دا \'kind\' لازمی \'plugin\' یا \'theme\' ہووے۔','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'manifest.json دا \'server_build_id\' درست بلڈ آئی ڈی نہیں۔','manifest.json\'s \'status\' must be \'published\'.'=>'manifest.json دا \'status\' لازمی \'published\' ہووے۔','nonce must be a hexadecimal string.'=>'nonce لازمی ہیکساڈیسیمل سٹرنگ ہووے۔','per day'=>'ہر روز','rc_…'=>'rc_…','sha256 mismatch for %s'=>'%s کِیتے sha256 بے میل','sha256 mismatch for default/%s'=>'default/%s کِیتے sha256 بے میل','component kind in the sweep brake messageplugin'=>'پلگ ان','component kind in the sweep brake messagetheme'=>'تھیم','problem report categoryOther'=>'ہور','translation statusAvailable'=>'دستیاب','translation statusInstalled'=>'انسٹال تھیا ہویا']];